@pytest.mark.parametrize('actual', ['resource_work_submission', 'resource_work_submission/api_resource_work_execution', 'resource_work_submission/local_resource_work_execution', 'resource_work_submission/hpc_resource_work_execution', 'resource_result_acquisition', 'scientific_process/resource_work_submission', 'scientific_process/resource_work_submission/api_resource_work_execution', 'scientific_process/resource_work_submission/local_resource_work_execution', 'scientific_process/resource_work_submission/hpc_resource_work_execution', 'scientific_process/resource_result_acquisition'], indirect=['actual'], ids=['home=resource_work_submission', 'home=resource_work_submission/api_resource_work_execution', 'home=resource_work_submission/local_resource_work_execution', 'home=resource_work_submission/hpc_resource_work_execution', 'home=resource_result_acquisition', 'home=scientific_process/resource_work_submission', 'home=scientific_process/resource_work_submission/api_resource_work_execution', 'home=scientific_process/resource_work_submission/local_resource_work_execution', 'home=scientific_process/resource_work_submission/hpc_resource_work_execution', 'home=scientific_process/resource_result_acquisition'])
def test_cross_context_reference_hooks_keep_original_registry_order(actual):
    v = actual
    reference = v.tools._source('controlled.resource.receipt', {'original': True})
    v.adapter.receipt = reference
    schema = {'type': 'object', 'properties': {'handoff': v.binding.fact_sources(v.role)['execution_handoff']['report_schema']}}
    form = {'handoff': handoff(v.adapter.selection)}
    expected = []
    for binding in v.registry._context_bindings(v.parent):
        callback = getattr(binding, 'received_form_references', None)
        if callback:
            expected.extend(callback(v.parent, form, schema, 'original-receipt'))
    assert v.registry.received_form_references(v.parent, form, schema, 'original-receipt') == list(dict.fromkeys(expected))
    assert reference in expected
    before = list(v.adapter.events)
    assert v.binding.received_form_references(v.parent, form, schema, 'foreign-context') == [reference]
    assert len(v.adapter.events) > len(before)

@pytest.mark.parametrize('actual', ['resource_work_submission', 'resource_work_submission/api_resource_work_execution', 'resource_work_submission/local_resource_work_execution', 'resource_work_submission/hpc_resource_work_execution', 'resource_result_acquisition', 'scientific_process/resource_work_submission', 'scientific_process/resource_work_submission/api_resource_work_execution', 'scientific_process/resource_work_submission/local_resource_work_execution', 'scientific_process/resource_work_submission/hpc_resource_work_execution', 'scientific_process/resource_result_acquisition'], indirect=['actual'], ids=['home=resource_work_submission', 'home=resource_work_submission/api_resource_work_execution', 'home=resource_work_submission/local_resource_work_execution', 'home=resource_work_submission/hpc_resource_work_execution', 'home=resource_result_acquisition', 'home=scientific_process/resource_work_submission', 'home=scientific_process/resource_work_submission/api_resource_work_execution', 'home=scientific_process/resource_work_submission/local_resource_work_execution', 'home=scientific_process/resource_work_submission/hpc_resource_work_execution', 'home=scientific_process/resource_result_acquisition'])
def test_original_fact_identity_order_and_typed_report_mismatch(actual):
    v = actual
    first = handoff(v.adapter.selection)
    later = {**first, 'checked_at': 'older-timestamp-last-supplied'}
    for adapter in v.adapters.values():
        adapter.handoffs = []
    v.adapter.handoffs = [first, later]
    facts = v.binding.facts(v.context, {})
    assert facts['execution_handoffs'] == [later] and facts['execution_handoff'] == later
    schema = {'type': 'object', 'properties': {'handoff': v.binding.fact_sources(v.role)['execution_handoff']['report_schema']}}
    v.binding.validate_report(v.context, {'handoff': later}, schema)
    with pytest.raises(own('communication').ReportBoundaryError) as caught:
        v.binding.validate_report(v.context, {'handoff': first}, schema)
    assert str(caught.value) == 'Resource handoff differs from selected recorded check'
