def test_handoff_check_original_fallback_and_protected_failure(actual, case):
    v = actual
    b = v.binding
    value = handoff(v.adapter.selection)
    error = ValueError('resource_information_identity_conflict' if case == 'protected' else 'original-invalid')

    async def asynchronous(*args):
        return v.adapter.outcome

    def synchronous(*args):
        if case in ('invalid', 'protected'):
            raise error
        return v.adapter.outcome
    callback = None if case == 'missing' else asynchronous if case == 'async' else synchronous
    with patch.object(v.adapter, 'check_handoff', callback):
        if v.role != 'launch':
            with pytest.raises(ValueError, match='^tool_not_owned_by_resource_role$'):
                asyncio.run(b.execute(v.context, 'resource.check_handoff', {'handoff': value}, 'original'))
        elif case == 'protected':
            with pytest.raises(ValueError) as caught:
                asyncio.run(b.execute(v.context, 'resource.check_handoff', {'handoff': value}, 'original'))
            assert caught.value is error
        else:
            result = asyncio.run(b.execute(v.context, 'resource.check_handoff', {'handoff': value}, 'original'))
            if case in ('sync', 'async'):
                assert result is v.adapter.outcome
            else:
                assert result['feedback']['code'] == ('receiving_interface_unavailable' if case == 'missing' else 'invalid_resource_handoff')

