def test_private_decision_state_retains_original_outcome_and_current_credit(actual, monkeypatch):
    v = actual
    task = make_task(v)
    captured = []
    unit = object()
    outcome = {'status': 'invalid', 'record_refs': [], 'changed_record_refs': [], 'feedback': {'code': 'controlled_invalid'}}
