    task.workflow = SimpleNamespace(run_id=v.journal.run_id, inprocess_replay=None, execution_binding=None, journal=v.journal, store=v.store, working_state=lambda source: {'records': []}, local_outcome_preview=lambda outcome, **kwargs: deepcopy(outcome), source_credit_view=lambda source: {'credit': 2.5}, receipt_projection=lambda source: False, source_credit_binding=lambda source: {'kind': 'operational'}, pending_work=lambda source: [], delivery_status=lambda episode: [], controller_binding={}, catalog=lambda *args, **kwargs: [], knowledge=SimpleNamespace(context=lambda: {}), job_episode_options=lambda source: [], extra_report_sources=lambda source: {}, specialist=lambda source: v.binding, binding_context=lambda source: v.context, is_scientific_source=lambda source: False, tools=object(), action_schema=lambda source: {})

    async def call(context, schema):
        captured.append(context)
        return ({}, 0, context, schema)
    task.call = call
    task.apply_response = lambda *args: unit
    view = SimpleNamespace(units_consumed=0, controller_state={}, child_reports=(), model_inputs=lambda state, **kwargs: state)
    assert asyncio.run(task.next(view)) is unit
    assert captured[0]['current_credit'] == 2.5 and captured[0]['last_local_outcome'] == outcome
    assert captured[0]['feedback'] == outcome['feedback'] and captured[0]['execution_assignment'] == v.assignment

